sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// Add your code here
	var targetSysId = current.getValue('correlation_id');
	try {
        // 1. Switch to the PATCH Update HTTP Method
        var request = new sn_ws.RESTMessageV2('Scripted API Instance A to B', 'Patch Method');

        // 2. Inject Instance B's sys_id into the ${target_sys_id} URL variable
        request.setStringParameterNoEscape('target_sys_id', targetSysId);

        // 3. correlation_id is no longer needed in the PATCH payload
        var payLoad = 
		{
            "opened_by": current.opened_by.toString(),
            "requestor": current.requestor.toString(),
            "type_of_asset": current.type_of_asset.toString(),
            "consumables": current.consumables.toString(),
            "company": current.company.toString(),
            "priority": current.priority.toString(),
            "short_description": current.short_description.toString(),
            "description": current.description.toString()
        };

        request.setRequestBody(JSON.stringify(payLoad));

        var response = request.execute();
        var httpStatus = response.getStatusCode();
        var responseBody = response.getBody();

        if(httpStatus == 200) {
            var parsedJson = JSON.parse(responseBody);
            gs.info("[Scripted API PATCH] Updated Instance B record. SysID: " + parsedJson.result.sys_id);
        } 
		else{
            gs.error("[Scripted API PATCH] Failed. Status: " + httpStatus + " Response: " + responseBody);
        }
    } 
	catch(ex) {
        gs.error("[Scripted API PATCH] Error: " + ex.getMessage());
    }

})(current, previous);
